from collections import Counter
def transform(g):
    h,w=len(g),len(g[0])
    cnt=Counter(x for r in g for x in r)
    bg=cnt.most_common(1)[0][0]
    out=[r[:] for r in g]
    for r in range(h):
        cs=[c for c in range(w) if g[r][c]!=bg]
        for a,b in zip(cs,cs[1:]):
            for c in range(a+1,b): out[r][c]=3
    for c in range(w):
        rs=[r for r in range(h) if g[r][c]!=bg]
        for a,b in zip(rs,rs[1:]):
            for r in range(a+1,b): out[r][c]=3
    return out
